#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using SporeGobbo.Geometry;using SporeGobbo.Safety;
/// <summary>Reproducible same-process region-entry trials. Explicit setup is excluded; ordinary samples run actual game systems without fixture writes, teleports, captures or forced collection.</summary>
public sealed class V1PerformanceEvidence:MonoBehaviour
{
 readonly List<string> checks=new List<string>(),errors=new List<string>(),memory=new List<string>();Keyboard keyboard;Mouse mouse;string directory;float deadline;bool finished;
 static T Find<T>()where T:UnityEngine.Object=>UnityEngine.Object.FindAnyObjectByType<T>();
 static bool Camp()=>Find<CampSceneController>()?.WorldInputReady==true&&Find<SettlementCampRegion>()?.Ready==true;
 static bool Expedition()=>Find<ExpeditionRegion>()?.PresentationReady==true&&Find<ExpeditionRegion>().Player!=null;
 void Awake(){directory=Persistence.ExperimentPath("Evidence");Directory.CreateDirectory(directory);deadline=Time.realtimeSinceStartup+1800;Application.logMessageReceived+=Observe;}
 void Observe(string m,string t,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)errors.Add(m+"\n"+t);}
 void Update(){if(!finished&&(errors.Count>0||Time.realtimeSinceStartup>deadline))Finish();}
 void Phase(string name){Stage61RuntimeMetrics.Category(name);Stage61RuntimeMetrics.Exclude(name,2);Stage61RuntimeMetrics.Mark(name);}
 void Check(string name,bool pass){checks.Add((pass?"PASS ":"FAIL ")+name);if(!pass)Finish();}
 IEnumerator Wait(Func<bool> ready,string name,float seconds=90){Phase("setup / "+name);float end=Time.realtimeSinceStartup+seconds;while(!finished&&!ready()&&Time.realtimeSinceStartup<end)yield return null;Check(name,!finished&&ready());}
 IEnumerator Ordinary(string name,float seconds,bool move=false){Phase("warmup / "+name);yield return new WaitForSecondsRealtime(2);Stage61RuntimeMetrics.Category("ordinary");Stage61RuntimeMetrics.Mark(name);float end=Time.realtimeSinceStartup+seconds;while(!finished&&Time.realtimeSinceStartup<end){if(move){float t=Time.realtimeSinceStartup;Key key=((int)(t*2)%4)==0?Key.D:((int)(t*2)%4)==1?Key.W:((int)(t*2)%4)==2?Key.A:Key.S;InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));}yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());Phase("end / "+name);}
 IEnumerator Start(){yield return null;yield return null;keyboard=InputSystem.AddDevice<Keyboard>("V1 performance keyboard");mouse=InputSystem.AddDevice<Mouse>("V1 performance mouse");keyboard.MakeCurrent();mouse.MakeCurrent();
 Check("owned evidence MainMenu entry",V1RuntimeProfile.EvidenceEnabled&&Persistence.Isolated&&SceneManager.GetActiveScene().name=="MainMenu");if(finished)yield break;
 Phase("canonical fixture import / Fresh A");DevelopmentCampaignFixtures.Import(1);Find<MainMenuController>().ContinueLastGame();yield return Wait(()=>Find<IntroRegion>()?.Player!=null&&Find<IntroRegion>().PresentationReady,"fixture Continue enters Intro");if(finished)yield break;
 var intro=Find<IntroRegion>();Check("Intro readiness includes prepared prompt resources",intro.Sequence.PresentationInitialized);Check("Intro birth clock excludes preparation interval",intro.Sequence.BirthTime<.05f);float birthWallBegin=Time.realtimeSinceStartup;Stage61RuntimeMetrics.Category("ordinary");Stage61RuntimeMetrics.Mark("Intro birth and quiet");while(!intro.ControlReady&&!finished)yield return null;Check("authored birth still requires 6.2 active seconds",intro.Sequence.BirthTime>=6.2f&&Time.realtimeSinceStartup-birthWallBegin>=6.1f);yield return new WaitForSeconds(3.2f);
 if(Environment.GetEnvironmentVariable("SPORE_STAGE61_CAPTURE")=="startup"){Phase("startup diagnostic complete");Check("actual Intro control released",intro.ControlReady);Finish();yield break;}
 for(int i=1;i<intro.Definition.Route.Length&&!finished;i++){if(i==8){yield return Walk(intro,new Point2(97.5,47.5));float until=Time.realtimeSinceStartup+20;while(!intro.Sequence.PlugCleared&&Time.realtimeSinceStartup<until){var screen=intro.RegionCamera.WorldToScreenPoint(intro.Render(intro.World(new Point2(100.5,47.5))));InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(screen.x,screen.y)});InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.LeftShift,Key.D));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());Phase("Intro dig check");Check("Intro plug cleared",intro.Sequence.PlugCleared);}yield return Walk(intro,intro.Definition.Route[i]);}
 yield return Wait(Camp,"Intro Camp arrival");if(finished)yield break;
 for(int trial=0;trial<10&&!finished;trial++){
  int target=trial==0?0:trial==1?5:10;Phase("canonical population setup / "+target);
  while(GameState.Instance.ownedGobbos.Count<target)Find<DevelopmentCampControls>().AddBuddy();
  Check("population "+trial,GameState.Instance.ownedGobbos.Count==target&&GameState.Instance.activeSquadIds.Count<=5);
  // Root assistance uses the existing eligibility check; fixture positioning is explicitly outside samples.
  if(target>0&&!Find<SettlementCampRegion>().ResidentialEntranceOpen){var camp=Find<SettlementCampRegion>();Find<DevelopmentCampControls>().Warp("camp.root.optional-pocket");var buddy=UnityEngine.Object.FindObjectsByType<BuddyUnit>(FindObjectsSortMode.None).FirstOrDefault();if(buddy!=null){var b=buddy.GetComponent<Rigidbody2D>();b.position=camp.ResidentialEntranceWorld;b.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();camp.TryOpenResidentialEntrance(Find<CampPlayableSpawner>().SpawnedPlayer);}Find<DevelopmentCampControls>().Warp("fire.watch");}
  Check("actual live Camp Buddy population "+trial,UnityEngine.Object.FindObjectsByType<BuddyUnit>(FindObjectsSortMode.None).Length==target);if(finished)yield break;
  yield return Ordinary("Camp construction-wander population="+target+" entry="+trial,trial<3?25:8);
  Phase("Camp save snapshot/write / "+trial);SporeSaveManager.SaveCurrentSlotFromGameState();yield return null;
  Phase("Camp departure / "+trial);var portal=Find<CampRunPortal>();portal.Interact(Find<CampPlayableSpawner>().SpawnedPlayer);portal.goButton.onClick.Invoke();yield return Wait(Expedition,"expedition entry "+trial);if(finished)yield break;
  var r=Find<ExpeditionRegion>();Check("God OFF / entry "+trial,!ExpeditionDevelopmentControls.GodMode);r.Player.Heal(r.Player.maxHealth);
  yield return Ordinary("expedition arrival movement entry="+trial,8,true);
  if(trial<3){
   Phase("dig approach setup");Warp(r,new Point2(20.5,94.5));yield return new WaitForSecondsRealtime(2);int before=r.Excavations;
   Stage61RuntimeMetrics.Category("ordinary");Stage61RuntimeMetrics.Mark("actual routed excavation trial="+trial);float end=Time.realtimeSinceStartup+3;while(Time.realtimeSinceStartup<end&&!finished){var s=r.RegionCamera.WorldToScreenPoint(r.Render(r.World(new Point2(20.5,90.5))));InputSystem.QueueStateEvent(mouse,new MouseState{position=new Vector2(s.x,s.y)});InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.LeftShift));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());Phase("excavation result");Check("real dig edits trial="+trial,r.Excavations>before);
   Phase("concealed breakthrough setup");Warp(r,new Point2(88.5,94.5));for(int y=93;y>=88;y--)r.DigCircle(r.World(new Point2(88.5,y+.5)),.9f);yield return Ordinary("discovery propagation trial="+trial,5);
   Phase("Weevil combat approach setup");Warp(r,new Point2(66.5,92.5));r.Player.Heal(r.Player.maxHealth);yield return Ordinary("real Weevil pursuit-melee GodOFF trial="+trial,3,true);Phase("post Weevil heal");Check("real Weevil instantiated trial="+trial,Find<TunnelWeevilEnemy>()!=null);r.Player.Heal(r.Player.maxHealth);
   Phase("Blob cover approach setup");Warp(r,new Point2(113.5,64.5));r.Player.Heal(r.Player.maxHealth);yield return Ordinary("real Blob ranged cover GodOFF trial="+trial,5,true);Phase("post Blob heal");Check("real Blob instantiated trial="+trial,Find<BlobSpitterEnemy>()!=null);r.Player.Heal(r.Player.maxHealth);
  }
  if(trial==9){Phase("real inventory grant for recruitment setup");r.Player.GetComponent<SporeInventory>().AddSpore(1);int rosterBefore=GameState.Instance.ownedGobbos.Count;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.Q));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return Wait(()=>Find<SporeGrow>()!=null,"real plant creates spore",15);yield return Ordinary("real spore hatch growth",5);yield return Wait(()=>Find<BuddyChoiceScreen>()?.panel.activeInHierarchy==true,"real hatch naming",25);if(finished)yield break;var choice=Find<BuddyChoiceScreen>();choice.nameInput.text="Performance recruit";choice.continueButton.onClick.Invoke();yield return Wait(()=>GameState.Instance.ownedGobbos.Count==rosterBefore+1,"real stable recruit enters roster",20);}
  Phase("real return transaction / "+trial);Check("return accepted "+trial,RunReturnService.ReturnToCamp("CampScene",true,true,trial%2==0?RunReturnReason.Retreat:RunReturnReason.NormalExit,"V1 performance real-service return"));yield return OpenReturn();if(finished)yield break;
  Phase("pause quit to Menu / "+trial);Find<PauseMenuController>().OpenPause();Find<PauseMenuController>().QuitToMainMenu();yield return Wait(()=>Find<MainMenuController>()!=null,"Menu teardown "+trial);yield return null;yield return null;
  Phase("forced GC and resource census OUTSIDE ordinary / "+trial);GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();SampleMemory(trial);
  Check("region teardown "+trial,DiggableTerrainService.Active==null&&Stage59ActorView.OwnedMeshes==0&&Stage59ActorView.OwnedMaterials==0&&Find<ExpeditionRegion>()==null&&Find<SettlementCampRegion>()==null);
  Find<MainMenuController>().ContinueLastGame();yield return Wait(Camp,"Continue Camp reentry "+trial);
 }
 if(finished)yield break;
 Phase("fake Camp return canonical builder outside benchmark");if(V1RuntimeProfile.DevelopmentToolsEnabled){var input=new FakeCompletedRunInput(0,0,0);Check("canonical fake return accepted",RunReturnService.ReturnSimulatedCampOutcome(()=>FakeCompletedRunBuilder.Apply(GameState.Instance,input)));yield return OpenReturn();}else Stage61RuntimeMetrics.Mark("tools-only fake return deferred to separate tools-ON proof");
 Finish();}
 void Warp(ExpeditionRegion r,Point2 p){var body=r.Player.GetComponent<Rigidbody2D>();body.position=r.World(p);body.linearVelocity=Vector2.zero;r.Player.transform.position=body.position;Physics2D.SyncTransforms();}
 void SampleMemory(int cycle){var all=Resources.FindObjectsOfTypeAll<MonoBehaviour>();memory.Add(cycle+","+GC.GetTotalMemory(false)+","+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()+","+Resources.FindObjectsOfTypeAll<Mesh>().Length+","+Resources.FindObjectsOfTypeAll<Material>().Length+","+Stage59ActorView.OwnedMeshes+","+Stage59ActorView.OwnedMaterials+","+UnityEngine.Object.FindObjectsByType<BuddyUnit>(FindObjectsSortMode.None).Length+","+all.Count(x=>x!=null&&x.GetType().Name.Contains("Rock"))+","+(DiggableTerrainService.Active==null?0:1)+","+UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Length);}
 IEnumerator OpenReturn(){yield return Wait(()=>Find<CampSceneController>()!=null,"return coordinator");float end=Time.realtimeSinceStartup+90;while(!finished&&!Camp()&&Time.realtimeSinceStartup<end){var c=Find<CampSceneController>();if(c.continueToSurvivorsButton!=null&&c.continueToSurvivorsButton.gameObject.activeInHierarchy)c.continueToSurvivorsButton.onClick.Invoke();else if(c.continueToCampButton!=null&&c.continueToCampButton.gameObject.activeInHierarchy)c.continueToCampButton.onClick.Invoke();yield return null;}Check("return ready",Camp());}
 IEnumerator Walk(IntroRegion r,Point2 target)
 {var goal=r.World(target);float end=Time.realtimeSinceStartup+40;while(!finished&&r!=null&&!r.Sequence.Arriving&&Vector2.Distance(r.Player.transform.position,goal)>.21f&&Time.realtimeSinceStartup<end){var d=goal-(Vector2)r.Player.transform.position;var keys=new List<Key>();if(d.x>.1f)keys.Add(Key.D);if(d.x<-.1f)keys.Add(Key.A);if(d.y>.1f)keys.Add(Key.W);if(d.y<-.1f)keys.Add(Key.S);InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys.ToArray()));yield return null;}InputSystem.QueueStateEvent(keyboard,new KeyboardState());Check("normal authored waypoint "+target,Time.realtimeSinceStartup<end);}

 void Finish(){if(finished)return;finished=true;Phase("evidence export outside ordinary");if(Time.realtimeSinceStartup>deadline)errors.Add("Performance proof exceeded 1800 second watchdog");Find<Stage61RuntimeMetrics>()?.Export();File.WriteAllLines(Path.Combine(directory,"memory-cycles.csv"),new[]{"cycle,managedBytes,nativeAllocatedBytes,allMeshes,allMaterials,ownedActorMeshes,ownedActorMaterials,activeBuddies,rockNamedComponents,terrainProviders,cameras"}.Concat(memory));File.WriteAllText(Path.Combine(directory,"result.json"),JsonUtility.ToJson(new Result{finished=true,error=errors.Count>0?"Performance proof failed":"",checks=checks.ToArray(),runtimeErrors=errors.ToArray(),method=Environment.GetEnvironmentVariable("SPORE_STAGE61_CAPTURE")=="startup"?"Startup diagnostic only: actual fixture Menu/Intro birth, release and quiet; no ten-cycle workload or lifecycle acceptance.":"10 same-process scene cycles; first 3 expedition entries are independent region instances, not independent processes. Setup, teleports, fixtures, save writes, forced GC and census excluded. Ordinary windows use real actors/AI/input; stationary windows include real Camp construction/wander. No God Mode. Tools-only fake return runs only in tools-ON profile; otherwise separate tools proof required. Resource census after Menu teardown and forced GC; allMeshes/materials include retained Unity assets; rockNamedComponents is a broad diagnostic count, not a hazard ownership claim."},true));Application.Quit(errors.Count==0&&!checks.Any(x=>x.StartsWith("FAIL "))?0:1);}
 [Serializable]sealed class Result{public bool finished;public string error,method;public string[] checks,runtimeErrors;}
 void OnDestroy(){Application.logMessageReceived-=Observe;if(keyboard!=null)InputSystem.RemoveDevice(keyboard);if(mouse!=null)InputSystem.RemoveDevice(mouse);}
}
#endif
